import '../models/certificate_model.dart'; import '../services/firestore_service.dart'; class CertificateRepository { final FirestoreService service; CertificateRepository({FirestoreService? service}):service=service??FirestoreService(); Future<void> save(CertificateModel x)=>service.setDoc('certificates',x.id,x.toMap()); Stream<List<CertificateModel>> byStudent(String id)=>service.stream('certificates').map((s)=>s.docs.map((d)=>CertificateModel.fromMap(d.id,d.data())).where((c)=>c.studentId==id).toList()); }